async function visitLedger(stream, visitor) {
  const reader = stream.getReader();

  let accepted = 0;
  let rejected = 0;
  let lineNumber = 0;
  let lineBuffer = "";
  let stopped = false;
  let cancelled = false;

  const decoder = new TextDecoder("utf-8");

  const cancelOnce = async () => {
    if (!cancelled) {
      cancelled = true;
      await reader.cancel();
    }
  };

  const processLine = async (line) => {
    lineNumber++;

    if (line.endsWith("\r")) {
      line = line.slice(0, -1);
    }

    if (line.trim() === "") {
      return;
    }

    let value;
    try {
      value = JSON.parse(line);
    } catch {
      rejected++;
      return;
    }

    accepted++;
    const result = await visitor({ line: lineNumber, value });

    if (result === false) {
      stopped = true;
    }
  };

  try {
    while (!stopped) {
      const result = await reader.read();

      if (result.done) {
        lineBuffer += decoder.decode();

        if (lineBuffer.length > 0) {
          await processLine(lineBuffer);
          lineBuffer = "";
        }

        break;
      }

      const text = decoder.decode(result.value, { stream: true });
      let start = 0;

      for (let i = 0; i < text.length; i++) {
        if (text.charCodeAt(i) === 10) {
          lineBuffer += text.slice(start, i);
          await processLine(lineBuffer);
          lineBuffer = "";
          start = i + 1;

          if (stopped) {
            break;
          }
        }
      }

      if (!stopped) {
        lineBuffer += text.slice(start);
      }
    }

    if (stopped) {
      await cancelOnce();
    }

    return { accepted, rejected, stopped };
  } catch (error) {
    await cancelOnce();
    throw error;
  } finally {
    reader.releaseLock();
  }
}
